const rows = $input.all().map(i => i.json);
const has_id = rows.some(r => r.update_id != null && r.update_id !== '');
const pad = $('Padronizar').first().json;
return [{ json: { ...pad, is_new: has_id } }];

const item = $input.first();
if (item.binary) {
  const keys = Object.keys(item.binary);
  if (keys.length && keys[0] !== 'data') {
    item.binary.data = item.binary[keys[0]];
  }
}
return [item];

const pad = $('Padronizar').first().json;
const raw = $input.first().json;
const txt = (raw.text || raw.transcription || '').toString().trim();
return [{ json: { ...pad, text: txt || 'Não entendi o áudio.', has_voice: false } }];

const pad = $('Padronizar').first().json;
const logItem = $('Log').first().json || {};
let textFromSetar = '';
try { const s = $('Setar Transcrição').first(); if (s?.json?.text != null) textFromSetar = String(s.json.text).trim(); } catch(e) {}
const text = textFromSetar !== '' ? textFromSetar : (logItem.text || pad.text || '');
const rows = $input.all().map(i => i.json).filter(r => r.id_tarefa);
if (rows.length === 0) {
  return [{ json: { chat_id: pad.chat_id, user_id: pad.user_id, text, has_waiting: false } }];
}
return [{ json: { chat_id: pad.chat_id, user_id: pad.user_id, text, has_waiting: true, waiting: rows[0] } }];

const d = $json;
const w = d.waiting || {};
return [{ json: {
  url: 'http://100.107.36.118:52049/api/agent',
  body: { task_id: w.id_tarefa, user_input: d.text, payload: w.payload || {} },
  chat_id: d.chat_id, id_tarefa: w.id_tarefa, agent_name: w.agent_name || 'Agente'
} }];

const res = $('Chamar Retomar').first().json;
const mr = $('Montar Retomar').first().json;
const isErr = res.error || (res.statusCode && res.statusCode >= 400);
let reply = isErr ? ('⚠️ Erro ao retomar: ' + (res.message || res.error || res.statusCode || 'erro desconhecido')) : (res.result_pt || res.reply_text || res.message || res.text || JSON.stringify(res));
const prefix = mr.agent_name ? '[' + mr.agent_name + '] ' : '';
return [{ json: { reply_text: prefix + reply, chat_id: mr.chat_id, generate_audio: false } }];

const pad = $('Tem Aguardando?').first().json;
const agentes = $input.all().map(i => i.json).filter(j => j.nome);
const catalogo = agentes.length
  ? agentes.map(a => '- ' + a.nome + ': ' + a.objetivo + ' | PODE: ' + a.pode + ' | NÃO PODE: ' + a.nao_pode + ' | FERRAMENTAS: ' + a.ferramentas).join('\n')
  : 'Nenhum agente criado. Pergunte se quer criar.';
return [{ json: { catalogo, text: pad.text, chat_id: pad.chat_id, user_id: pad.user_id } }];

const raw = $input.first().json;
let content = '';
if (typeof raw.output === 'string') content = raw.output;
else if (typeof raw.output === 'object') content = JSON.stringify(raw.output);
else content = raw.content || raw.text || JSON.stringify(raw);

let p = {};
try { const m = content.match(/\{[\s\S]*\}/); p = m ? JSON.parse(m[0]) : {}; } catch(e) { p = {}; }

if (!p.reply_text) p.reply_text = content;
if (!p.action) p.action = null;
if (!p.need_approval) p.need_approval = false;
if (!p.need_user_input) p.need_user_input = null;
if (!p.generate_audio) p.generate_audio = false;

const ctx = $('Contexto').first().json;
if (String(ctx.text || '').toUpperCase().includes('CONFIRMO ALFA')) p.need_approval = false;

return [{ json: { ...p, chat_id: ctx.chat_id, user_id: ctx.user_id } }];

const g = $input.first().json;
let rota = 0;
if (g.need_user_input) rota = 3;
else if (g.need_approval && g.action) rota = 1;
else if (g.action && !g.need_approval) rota = 2;
return [{ json: { ...g, rota } }];

const e = $input.first().json;
const esc = s => String(s ?? '').replace(/'/g, "''");
return [{ json: { chat_id: e.chat_id, user_id: e.user_id, pedido_esc: esc(e.reply_text), previa_esc: esc(e.approval_preview || e.reply_text), acao_json: JSON.stringify(e.action || {}).replace(/'/g, "''") } }];

const row = $input.first().json;
const id = row.id;
const prev = $('Prep Pendência').first().json;
const txt = '👀 *PRÉVIA #' + id + '*

' + prev.previa_esc + '

✅ "aprovar ' + id + '"
❌ "cancelar ' + id + '"
⚡ Ou: CONFIRMO ALFA';
return [{ json: { txt, chat_id: prev.chat_id } }];

const e = $input.first().json;
const action = e.action || {};
const tipo = (action.type || '').toLowerCase();
const payload = action.payload || {};
const internal = ['criar_agente','editar_agente','aprovar_pendencia','cancelar_pendencia','consultar_sql'];
const task_id = Date.now() + '-' + Math.random().toString(36).substring(2,9);
const agent_name = tipo === 'openclaw' ? 'OpenClaw' : (tipo === 'executar_pc' ? 'PC' : tipo);
return [{ json: { ...e, tipo, payload, task_id, agent_name, exec_type: internal.includes(tipo) ? 'internal' : 'external' } }];

const e = $input.first().json;
const tipo = e.tipo;
let endpoint = '', headers = {'Content-Type':'application/json'}, timeout = 120000;
if (tipo === 'openclaw') { endpoint = 'http://100.107.36.118:52049/api/agent'; }
else if (tipo === 'executar_pc') { endpoint = 'http://100.107.36.118:8787'; headers['X-AGENT-TOKEN'] = 'MEU_TOKEN_FORTE_123'; timeout = 30000; }
else { endpoint = 'http://100.107.36.118:52049/api/agent'; }
const body = { ...e.payload, task_id: e.task_id, agent_name: e.agent_name };
return [{ json: { endpoint, headers: JSON.stringify(headers), body: JSON.stringify(body), timeout, chat_id: e.chat_id, user_id: e.user_id, task_id: e.task_id, agent_name: e.agent_name, reply_text: e.reply_text, tipo: e.tipo } }];

const res = $input.first().json;
const ep = $('Montar Endpoint').first().json;

// Detectar timeout/erro
const is_error = res.error || res.code === 'ETIMEDOUT' || res.code === 'ECONNREFUSED' || (res.statusCode && res.statusCode >= 400);
if (is_error) {
  return [{ json: { reply_text: '⚠️ ERRO: ' + (ep.agent_name || 'Agente') + ' não respondeu (timeout ou erro). Tarefa cancelada.', chat_id: ep.chat_id, user_id: ep.user_id, task_id: ep.task_id, agent_name: ep.agent_name, need_input: false, is_error: true, tipo: ep.tipo } }];
}

const need_input = res.need_input === true;
const reply = res.result_pt || res.reply_text || res.message || '';
return [{ json: { ...res, reply_text: reply || ep.reply_text, chat_id: ep.chat_id, user_id: ep.user_id, task_id: ep.task_id, agent_name: ep.agent_name, need_input, is_error: false, tipo: ep.tipo } }];

const e = $('Parse Agente').first().json;
const nome = e.agent_name || 'OpenClaw';
const id = e.task_id || '';
const prompt = e.prompt_pt || e.instrucao || e.reply_text || 'Me envie o código aqui.';
const tipo = (e.input_type || 'otp').toLowerCase();
let extra = '';
if (tipo === 'captcha') extra = ' Resolva e responda OK.';
const txt = '[' + nome + ' • tarefa ' + id + '] ' + prompt + extra;
return [{ json: { txt, chat_id: e.chat_id } }];

const e = $input.first().json;
const txt = e.is_error ? e.reply_text : (e.reply_text + '\n\n✅ Executado.');
const prefix = e.agent_name ? '[' + e.agent_name + '] ' : '';
return [{ json: { reply_text: prefix + txt, chat_id: e.chat_id, user_id: e.user_id } }];

const e = $input.first().json;
const tipo = e.tipo;
const payload = e.payload || {};
const esc = s => String(s ?? '').replace(/'/g, "''");
let sql = ''; let extra = ''; let reexecutar = false;

switch(tipo) {
  case 'criar_agente':
    sql = "INSERT INTO general_agentes (nome,objetivo,pode,nao_pode,ferramentas,prompt_sistema) VALUES ('" + esc(payload.nome) + "','" + esc(payload.objetivo) + "','" + esc(payload.pode) + "','" + esc(payload.nao_pode) + "','" + esc(payload.ferramentas) + "','" + esc(payload.prompt_sistema) + "') ON CONFLICT (nome) DO UPDATE SET objetivo=EXCLUDED.objetivo,pode=EXCLUDED.pode,nao_pode=EXCLUDED.nao_pode,ferramentas=EXCLUDED.ferramentas,prompt_sistema=EXCLUDED.prompt_sistema,ativo=TRUE RETURNING id,nome;";
    extra = '✅ Agente criado.'; break;
  case 'editar_agente':
    sql = "UPDATE general_agentes SET objetivo='" + esc(payload.objetivo) + "',pode='" + esc(payload.pode) + "',nao_pode='" + esc(payload.nao_pode) + "',ferramentas='" + esc(payload.ferramentas) + "',prompt_sistema='" + esc(payload.prompt_sistema) + "' WHERE nome='" + esc(payload.nome) + "' RETURNING id,nome;";
    extra = '✅ Agente editado.'; break;
  case 'aprovar_pendencia':
    sql = "UPDATE general_pending SET status='APROVADO' WHERE id=" + Number(payload.id) + " AND status='PENDENTE' RETURNING id,acao;";
    extra = '✅ Pendência #' + payload.id + ' aprovada.';
    reexecutar = true; break;
  case 'cancelar_pendencia':
    sql = "UPDATE general_pending SET status='CANCELADO' WHERE id=" + Number(payload.id) + " AND status='PENDENTE' RETURNING id;";
    extra = '❌ Pendência #' + payload.id + ' cancelada.'; break;
  case 'consultar_sql':
    sql = payload.query || 'SELECT 1;'; extra = ''; break;
  default:
    sql = 'SELECT 1;'; extra = '⚠️ Ação não reconhecida.';
}
return [{ json: { sql, extra, reply_text: e.reply_text, chat_id: e.chat_id, user_id: e.user_id, tipo, reexecutar } }];

const rows = $input.all().map(i => i.json);
const prev = $('Montar SQL').first().json;
let reply = prev.reply_text || '';
if (prev.extra) reply += '\n' + prev.extra;

// Se é consulta, mostrar resultado
if (prev.tipo === 'consultar_sql' && rows.length && rows[0] && Object.keys(rows[0]).length > 0) {
  reply += '\n\n📊 ' + JSON.stringify(rows, null, 2).substring(0, 3000);
}

// Se é aprovação, extrair acao pra reexecutar
let reexecutar = false;
let acao = null;
if (prev.reexecutar && rows.length && rows[0]?.acao) {
  try {
    acao = typeof rows[0].acao === 'string' ? JSON.parse(rows[0].acao) : rows[0].acao;
    reexecutar = true;
    reply += '\n⏳ Executando ação aprovada...';
  } catch(e) {}
}

return [{ json: { reply_text: reply, chat_id: prev.chat_id, user_id: prev.user_id, reexecutar, acao } }];

const g = $input.first().json;
const inp = g.need_user_input || {};
const task_id = Date.now() + '-' + Math.random().toString(36).substring(2,9);
const agent_name = 'General';
const input_type = inp.input_type || 'otp';
const prompt_pt = inp.prompt_pt || g.reply_text || 'Me envie o código aqui.';
const has_image = inp.has_image || false;
return [{ json: { chat_id: g.chat_id, task_id, agent_name, input_type, prompt_pt, has_image, payload: inp.payload || {}, reply_text: g.reply_text } }];

const e = $('Prep Input General').first().json;
const tipo = (e.input_type || 'otp').toLowerCase();
let extra = '';
if (tipo === 'captcha') extra = ' Resolva e responda OK.';
const txt = '[' + e.agent_name + ' • tarefa ' + e.task_id + '] ' + e.prompt_pt + extra;
return [{ json: { txt, chat_id: e.chat_id } }];

const e = $input.first().json;
const acao = e.acao || {};
const tipo = (acao.type || '').toLowerCase();
const payload = acao.payload || {};
const task_id = Date.now() + '-' + Math.random().toString(36).substring(2,9);
const agent_name = tipo === 'openclaw' ? 'OpenClaw' : (tipo === 'executar_pc' ? 'PC' : tipo);

let endpoint = '', headers = {'Content-Type':'application/json'}, timeout = 120000;
if (tipo === 'openclaw') { endpoint = 'http://100.107.36.118:52049/api/agent'; }
else if (tipo === 'executar_pc') { endpoint = 'http://100.107.36.118:8787'; headers['X-AGENT-TOKEN'] = 'MEU_TOKEN_FORTE_123'; timeout = 30000; }
else { endpoint = 'http://100.107.36.118:52049/api/agent'; }

const body = { ...payload, task_id, agent_name };
return [{ json: { endpoint, headers: JSON.stringify(headers), body: JSON.stringify(body), timeout, chat_id: e.chat_id, user_id: e.user_id, task_id, agent_name, reply_text: e.reply_text, tipo } }];

const res = $input.first().json;
const prep = $('Prep Reexecução').first().json;
const is_error = res.error || res.code === 'ETIMEDOUT' || (res.statusCode && res.statusCode >= 400);
let reply = prep.reply_text || '';
if (is_error) { reply += '\n⚠️ Erro ao executar ação aprovada.'; }
else { reply += '\n✅ Ação aprovada executada com sucesso.'; }
return [{ json: { reply_text: reply, chat_id: prep.chat_id } }];
